// 保存原始请求数据和API配置
const request = $input.first().json.body || $input.first().json;

// 配置API密钥 - 请在此处填入您的密钥
const config = {
  AMAP_API_KEY: 'c900719xxxx'
};

return [{ 
  json: {
    ...request,
    _config: config
  }
}];

// 处理景点搜索结果
const response = $input.first().json;
const attractions = (response.pois || []).slice(0, 10).map(poi => ({
  name: poi.name,
  address: poi.address,
  location: poi.location,
  type: poi.type,
  tel: poi.tel || '',
  rating: poi.biz_ext?.rating || '',
  photos: poi.photos || []
}));

return [{ json: { attractions, status: response.status } }];

// 处理天气查询结果
const response = $input.first().json;
const forecasts = response.forecasts?.[0]?.casts || [];
const weather = forecasts.map(cast => ({
  date: cast.date,
  dayweather: cast.dayweather,
  nightweather: cast.nightweather,
  daytemp: cast.daytemp,
  nighttemp: cast.nighttemp,
  daywind: cast.daywind,
  nightwind: cast.nightwind,
  daypower: cast.daypower,
  nightpower: cast.nightpower
}));

return [{ json: { weather, status: response.status } }];

// 处理酒店搜索结果
const response = $input.first().json;
const hotels = (response.pois || []).slice(0, 5).map(poi => ({
  name: poi.name,
  address: poi.address,
  location: poi.location,
  type: poi.type,
  tel: poi.tel || '',
  rating: poi.biz_ext?.rating || ''
}));

return [{ json: { hotels, status: response.status } }];

// 整合所有数据
const items = $input.all();

// 从保存请求数据节点获取原始请求
const savedData = $('保存请求数据').first().json;
const savedRequest = savedData;
const config = savedData._config;

// 提取各类数据
let attractions = [];
let weather = [];
let hotels = [];

for (const item of items) {
  if (item.json.attractions) {
    attractions = item.json.attractions;
  }
  if (item.json.weather) {
    weather = item.json.weather;
  }
  if (item.json.hotels) {
    hotels = item.json.hotels;
  }
}

return [{
  json: {
    request: {
      city: savedRequest.city || '',
      start_date: savedRequest.start_date || '',
      end_date: savedRequest.end_date || '',
      travel_days: savedRequest.travel_days || 3,
      transportation: savedRequest.transportation || '公共交通',
      accommodation: savedRequest.accommodation || '经济型酒店',
      preferences: savedRequest.preferences || [],
      free_text_input: savedRequest.free_text_input || ''
    },
    attractions: attractions,
    weather: weather,
    hotels: hotels,
    _config: config
  }
}];

